/* ============================================================================
 * CONTENT · 13-year-tales.js
 * 年终随笔的素材库。引擎的 P.yearNarrative() 按顺序挑三段：
 *   did  —— 这一年你做了什么（按忙闲/头条数）
 *   gain —— 你得到/失去了什么（按 rep/fun/hp/lev/tier 的年度差值）
 *   now  —— 你现在站在哪（按层级/州/处境的白描）
 *
 * 字段：kind（三选一）+ when（统一条件词汇）+ texts（同条件多个写法随机挑）
 * 模板变量：{name} {year} {age} {state} {dRep} {dFun} {dHp} {tier}
 * when 里可用引擎塞进快照的差值布尔：upRep/downRep/upFun/downFun/upHp/downHp/
 *   upTier/downTier/busyYear/quietYear/fallen/heads
 *
 * 写作纪律（同 08-vignettes.js）：
 *   ① 全角引号一律用「」，不用 ASCII 双引号（SyntaxError 的源头）
 *   ② 散文里不写精确数字 —— 数字在下面的 yearbar 里，这里只给体感
 *   ③ 每个 kind 至少一条无条件兜底，任何处境都要拼得出三段
 * ==========================================================================*/
POTUS.define("yeartale", {
  /* ---------- 这一年你做了什么 ---------- */
  yt_did_busy: {
    kind: "did", when: { cond: function (s) { return s.busyYear; } },
    texts: [
      "{year} 年是被电话、行程和意外塞满的一年。你后来只记得几个片段：某个深夜的电话、某间烟味散不掉的会议室、某张签名之前手悬了很久的纸。其余的日子相互淹没，像雨落进河里。",
      "这一年几乎没有喘气的月份。人们后来总结你的 {year}，用的全是动作动词——出席、否决、斡旋、否认。只有你知道，每个动作之间隔着多少个睡不着的夜晚。",
      "{year} 年的日历翻得比哪一年都快。等你抬头，树已经绿了又黄。你做了很多事，也得罪了很多人——这两件事在政治里往往是同一件事。"
    ]
  },
  yt_did_quiet: {
    kind: "did", when: { cond: function (s) { return s.quietYear; } },
    texts: [
      "{year} 年几乎什么都没发生。没有危机，没有转机，连对手都懒得提起你的名字。这样的年份在回忆录里只值一句话，可你是靠着这一年喘的气。",
      "平静的 {year} 年。你读完了搁在床头两年的那摞书，陪家人吃了几顿完整的晚饭。报纸上没有你的版面——你有时候怀疑这是不是一种失败，后来才懂这是一种储蓄。",
      "{year} 年无声地过去了。政治生涯里大部分年份都是这样的：没有舞台，只有排练。你在等一个还没来的年代。"
    ]
  },
  yt_did_normal: {
    kind: "did",
    texts: [
      "{year} 年有起有落，但都算不上惊涛。你按部就班地做事，偶尔上一次报纸，偶尔被人遗忘。政治生活的大部分就是这样的中音区。",
      "这一年过得像一条熟悉的上班路线：有几天绕了远，有几天赶上了绿灯。{name} 的 {year} 年，写下来不过寥寥数行。"
    ]
  },
  yt_did_headlines: {
    kind: "did", when: { cond: function (s) { return s.heads >= 3; } },
    texts: [
      "{year} 年你上了太多次头条——不全是好的那种。剪报册厚了一指，你开始明白版面是租来的，租金迟早要付。",
      "这是被标题定义的一年。编辑们给你的 {year} 年挑的形容词，你一个都不认同，但你学会了不跟报纸吵架。"
    ]
  },

  /* ---------- 你得到/失去了什么 ---------- */
  yt_gain_up: {
    kind: "gain", when: { cond: function (s) { return s.upTier || (s.upRep && s.upFun); } },
    texts: [
      "账目上说，这一年你是赚的：名声大了一点，位置高了一点，口袋厚了一点。你在年终的账本上看到自己的上升，也在镜子里看到它收的利息——眼角的纹路深了。",
      "你往上走了一段。有人开始用敬语叫你的头衔，也有人开始在背地里查你的底细。得到的东西各有各的名字，失去的东西只有一个名字：从容。"
    ]
  },
  yt_gain_down: {
    kind: "gain", when: { cond: function (s) { return s.downTier || s.downRep || s.downFun; } },
    texts: [
      "这一年是往回走的。声望、位置或存款，总有一样从你手里漏了出去——具体是哪一样，要看账本才知道；但那种下沉的感觉，不用看账本你也知道。",
      "你失去了不少。支持者的来信变薄了，邀请函的措辞变冷了。有一瞬间你想过改行，随后你又想到：除了这个，你其实什么都不会。"
    ]
  },
  yt_gain_health: {
    kind: "gain", when: { cond: function (s) { return s.downHp; } },
    texts: [
      "身体先于账本报警。今年体检报告上的箭头比去年多，你把报告折起来放进抽屉，跟那些「以后再说」的文件放在一起。"
    ]
  },
  yt_gain_flat: {
    kind: "gain",
    texts: [
      "得失相抵的一年——或者说，都没到值得记账的数目。你的筹码还是那些筹码，只是又旧了一年。",
      "没有大赚，也没有大赔。你守住了自己的位置，像守一条河的堤：新闻里不会报道堤坝没垮，但你知道这意味着什么。"
    ]
  },
  yt_gain_fallen: {
    kind: "gain", when: { flags: ["fallen"] },
    texts: [
      "这一年你从台上摔了下去。具体过程不愿再想，结论人尽皆知。人们以为故事到这里就结束了——你决定不这么写。",
      "下野之后的头几个月，电话安静得可怕。后来你把安静当成了一种资源：终于有时间想清楚，哪些东西摔不掉。"
    ]
  },

  /* ---------- 你现在站在哪 ---------- */
  yt_now_low: {
    kind: "now", when: { maxTier: 1 },
    texts: [
      "你现在站在台阶的最下面几级，{state}。没有人欠你人情，也没有人怕你——这两件事将来会一起改变，或者一起不变。",
      "你在 {state} 的基层，名片递出去，十个人里有九个要看两眼才想起你是谁。政治对你来说还是别人的游戏，但你的票已经投进去了：投给了自己。"
    ]
  },
  yt_now_mid: {
    kind: "now", when: { minTier: 2, maxTier: 3 },
    texts: [
      "你现在是 {state} 说得上话的人了。会有人专门来问你的意见，也有人专门防着你说的话。中间这几级台阶最宽敞，也最拥挤——上下左右全是要跟你握手或者绊你的人。",
      "站在 {tier} 的位置上，你已经能看到权力的门槛——也看到了门槛上磨得发亮的那道痕：多少人从这里进去，多少人从这里出来。"
    ]
  },
  yt_now_high: {
    kind: "now", when: { minTier: 4 },
    texts: [
      "你现在站的地方，风景很好，风也很大。{state} 已经装不下你的名字，你的每句话都会被三个渠道同时解读。往上只剩最后一级台阶——和深渊。",
      "身居 {tier}，你终于明白这个游戏的顶部长什么样：不是更大的权力，而是更少的退路。你的每一步都有人在录像。"
    ]
  },
  yt_now_fallen: {
    kind: "now", when: { flags: ["fallen"] },
    texts: [
      "你从台上下来之后，{state} 的街道还是原来的街道。有人躲着你的目光，也有人握你的手握得更用力了一点。你记下了这两种人。",
      "现在你站在人群里，而不是台子上。看问题的角度忽然不一样了——早几年从这个角度看过一次，也许就不会摔下来。"
    ]
  },
  yt_now_default: {
    kind: "now",
    texts: [
      "年关的时候你站在办公室窗前。{state} 的灯一盏一盏亮着，每一盏底下都有你的选民、你的债主或你的敌人。你数了一会儿，然后关灯下班。",
      "{year} 年的最后一天，你把钢笔帽拧上。这一年无论怎样都过去了——政治教给你的第一课就是：只要还在牌桌上，下一局就还没开始。"
    ]
  }
});
